export const listConnectionChannelsPathConnectionIdRegExp = new RegExp('^[A-HJKMNP-TV-Za-hjkmnp-tv-z]{1,2}[0-9A-TV-Za-tv-z]{12}$');


export const ListConnectionChannelsParams = zod.object({
  "connection_id": zod.string().regex(listConnectionChannelsPathConnectionIdRegExp).describe('Connection `public_id`.')
})

export const ListConnectionChannelsQueryParams = zod.object({
  "team_id": zod.string().optional().describe('Only this team.'),
  "q": zod.string().optional().describe('Match on channel name.')
})

export const ListConnectionChannelsResponse = zod.object({
  "items": zod.array(zod.object({
  "id": zod.string(),
  "name": zod.string(),
  "display_name": zod.string(),
  "team_id": zod.string(),
  "team_name": zod.string(),
  "type": zod.enum(['open', 'private', 'direct', 'group']),
  "archived": zod.boolean().optional()
}))
})

